import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';
import { apiLayThongBao, apiGuiThongBao } from '../../api/goi_api';

const QuanLyThongBao = () => {
    const [tabActive, setTabActive] = useState('view');
    const [title, setTitle] = useState('');
    const [content, setContent] = useState('');
    const [notifications, setNotifications] = useState([]);
    const [loading, setLoading] = useState(true);

    const user = JSON.parse(sessionStorage.getItem('user') || '{}');

    const fetchNotifications = async () => {
        try {
            setLoading(true);
            const res = await apiLayThongBao();
            setNotifications(res.data || []);
        } catch (error) {
            console.error('Lỗi lấy thông báo:', error);
            alert('Không thể tải danh sách thông báo!');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchNotifications();
    }, []);

    const handleSendNotification = async () => {
        if (!title.trim() || !content.trim()) {
            return alert('Vui lòng nhập tiêu đề và nội dung thông báo!');
        }

        if (!user?.id) {
            return alert('Không tìm thấy tài khoản đăng nhập!');
        }

        try {
            await apiGuiThongBao({
                id_nguoi_gui: user.id,
                tieu_de: title.trim(),
                noi_dung: content.trim()
            });

            alert('Gửi thông báo thành công!');
            setTitle('');
            setContent('');
            setTabActive('view');
            fetchNotifications();
        } catch (error) {
            console.error('Lỗi gửi thông báo:', error);
            const msg = error.response?.data?.message || 'Gửi thông báo thất bại!';
            alert(msg);
        }
    };

    return (
        <div style={containerStyle} className="glass-card">
            <div style={headerTabStyle}>
                <button
                    onClick={() => setTabActive('view')}
                    style={{
                        ...tabButtonStyle,
                        backgroundColor: tabActive === 'view' ? '#333' : 'rgba(255,255,255,0.6)',
                        color: tabActive === 'view' ? '#fff' : '#333'
                    }}
                >
                    Khung thông báo
                </button>

                <button
                    onClick={() => setTabActive('send')}
                    style={{
                        ...tabButtonStyle,
                        backgroundColor: tabActive === 'send' ? '#8b5e5e' : 'rgba(255,255,255,0.6)',
                        color: tabActive === 'send' ? '#fff' : '#333'
                    }}
                >
                    Gửi thông báo
                </button>
            </div>

            <div style={{ flex: 1, padding: '20px', overflow: 'hidden' }}>
                {tabActive === 'view' ? (
                    <div className="custom-scrollbar" style={scrollContainerStyle}>
                        {loading ? (
                            <div style={emptyStateStyle}>Đang tải thông báo...</div>
                        ) : notifications.length > 0 ? (
                            notifications.map((noti) => (
                                <div key={noti.id} style={notiCardStyle}>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                                            <span style={roomTagStyle}>📢 THÔNG BÁO</span>
                                            <span style={{ fontWeight: 'bold', color: '#333' }}>{noti.tieu_de}</span>
                                        </div>
                                        <span style={{ fontSize: '12px', color: '#999' }}>
                                            {new Date(noti.ngay_gui).toLocaleString('vi-VN')}
                                        </span>
                                    </div>

                                    <p style={{ ...notiBodyStyle, marginBottom: '8px' }}>{noti.noi_dung}</p>

                                    <div style={{ fontSize: '12px', color: '#777', fontStyle: 'italic' }}>
                                        Người gửi: {noti.nguoi_gui || 'ad'}
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div style={emptyStateStyle}>Chưa có thông báo nào.</div>
                        )}
                    </div>
                ) : (
                    <div style={sendFormStyle}>
                        <div style={{ display: 'flex', gap: '15px' }}>
                            <select style={roomSelectStyle} value="All" disabled>
                                <option value="All">Gửi toàn tòa nhà</option>
                            </select>

                            <input
                                style={{ ...inputStyle, flex: 1 }}
                                placeholder="Tiêu đề thông báo..."
                                value={title}
                                onChange={(e) => setTitle(e.target.value)}
                            />
                        </div>

                        <textarea
                            style={textareaStyle}
                            placeholder="Nội dung thông báo chi tiết..."
                            value={content}
                            onChange={(e) => setContent(e.target.value)}
                        />

                        <button
                            onClick={handleSendNotification}
                            disabled={!title.trim() || !content.trim()}
                            style={{
                                ...btnSendStyle,
                                opacity: title.trim() && content.trim() ? 1 : 0.5
                            }}
                        >
                            Gửi ngay
                        </button>
                    </div>
                )}
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 6px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.3); border-radius: 10px; }
            `}</style>
        </div>
    );
};

const containerStyle = {
    flex: 1,
    borderRadius: '30px',
    display: 'flex',
    flexDirection: 'column',
    backgroundImage: `url(${chatBgImg})`,
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    overflow: 'hidden',
    position: 'relative',
    height: 'calc(100vh - 120px)'
};

const headerTabStyle = {
    padding: '20px',
    display: 'flex',
    gap: '15px',
    flexShrink: 0,
    background: 'rgba(0,0,0,0.1)'
};

const scrollContainerStyle = {
    height: '100%',
    overflowY: 'auto',
    display: 'flex',
    flexDirection: 'column',
    gap: '12px',
    paddingRight: '10px'
};

const tabButtonStyle = {
    padding: '10px 25px',
    borderRadius: '20px',
    border: 'none',
    fontWeight: 'bold',
    cursor: 'pointer',
    transition: '0.3s'
};

const notiCardStyle = {
    backgroundColor: 'rgba(255,255,255,0.95)',
    padding: '20px',
    borderRadius: '20px',
    position: 'relative',
    flexShrink: 0,
    boxShadow: '0 4px 15px rgba(0,0,0,0.05)'
};

const roomTagStyle = {
    backgroundColor: '#333',
    color: '#fff',
    padding: '4px 12px',
    borderRadius: '8px',
    fontSize: '10px',
    fontWeight: 'bold'
};

const notiBodyStyle = {
    margin: 0,
    fontSize: '14px',
    color: '#444',
    lineHeight: '1.6',
    whiteSpace: 'pre-wrap'
};

const sendFormStyle = {
    backgroundColor: 'rgba(255,255,255,0.2)',
    backdropFilter: 'blur(10px)',
    borderRadius: '25px',
    padding: '25px',
    display: 'flex',
    flexDirection: 'column',
    gap: '15px'
};

const roomSelectStyle = {
    padding: '12px',
    borderRadius: '12px',
    border: 'none',
    outline: 'none',
    fontWeight: 'bold',
    backgroundColor: '#fff',
    cursor: 'pointer'
};

const inputStyle = {
    padding: '12px',
    borderRadius: '12px',
    border: 'none',
    outline: 'none',
    fontSize: '15px'
};

const textareaStyle = {
    width: '100%',
    height: '160px',
    padding: '15px',
    borderRadius: '12px',
    border: 'none',
    outline: 'none',
    resize: 'none',
    fontSize: '14px'
};

const btnSendStyle = {
    alignSelf: 'flex-end',
    padding: '12px 40px',
    borderRadius: '12px',
    border: 'none',
    backgroundColor: '#8b5e5e',
    color: '#fff',
    fontWeight: 'bold',
    cursor: 'pointer'
};

const emptyStateStyle = {
    textAlign: 'center',
    color: '#fff',
    marginTop: '50px',
    opacity: 0.8
};

export default QuanLyThongBao;
